{extern int __CanOpen_SDORead(int, unsigned char, unsigned short, unsigned char);}
{extern int __CanOpen_SDOResult(int, unsigned char, int, unsigned int*, unsigned int*);}
CASE STATE OF
  0:
    IF EXECUTE AND NOT EXECUTE0 THEN
      STATE := 1;
      DONE := FALSE;
      ERROR := FALSE;
      ERRORID := 0;
      VALUE := 0;
      BUSY := TRUE;
    END_IF;
  1:
    {{
      if(__CanOpen_SDORead(__GET_VAR(data__->NETWORK),
                           __GET_VAR(data__->NODEID),
                           __GET_VAR(data__->INDEX),
                           __GET_VAR(data__->SUBINDEX)) == 0){
          __SET_VAR(data__->,STATE,, 2);
      }else{
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  2:
    {{
      unsigned int value = 0, abortcode = 0;
      int res = __CanOpen_SDOResult(__GET_VAR(data__->NETWORK),
                                    __GET_VAR(data__->NODEID),
                                    1, &value, &abortcode);
      if(res > 0){
          __SET_VAR(data__->,VALUE,, value);
          __SET_VAR(data__->,DONE,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }else if(res < 0){
          __SET_VAR(data__->,ERRORID,, abortcode);
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  3:
    BUSY := FALSE;
    IF NOT EXECUTE THEN
      STATE := 0;
      DONE := FALSE;
      ERROR := FALSE;
    END_IF;
ELSE
  STATE := 0;
END_CASE;

EXECUTE0 := EXECUTE;

{extern int __CanOpen_SDOWrite(int, unsigned char, unsigned short, unsigned char, unsigned char, unsigned int);}
{extern int __CanOpen_SDOResult(int, unsigned char, int, unsigned int*, unsigned int*);}
CASE STATE OF
  0:
    IF EXECUTE AND NOT EXECUTE0 THEN
      STATE := 1;
      DONE := FALSE;
      ERROR := FALSE;
      ERRORID := 0;
      BUSY := TRUE;
    END_IF;
  1:
    {{
      if(__CanOpen_SDOWrite(__GET_VAR(data__->NETWORK),
                            __GET_VAR(data__->NODEID),
                            __GET_VAR(data__->INDEX),
                            __GET_VAR(data__->SUBINDEX),
                            __GET_VAR(data__->SIZE),
                            __GET_VAR(data__->VALUE)) == 0){
          __SET_VAR(data__->,STATE,, 2);
      }else{
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  2:
    {{
      unsigned int value = 0, abortcode = 0;
      int res = __CanOpen_SDOResult(__GET_VAR(data__->NETWORK),
                                    __GET_VAR(data__->NODEID),
                                    0, &value, &abortcode);
      if(res > 0){
          __SET_VAR(data__->,DONE,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }else if(res < 0){
          __SET_VAR(data__->,ERRORID,, abortcode);
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  3:
    BUSY := FALSE;
    IF NOT EXECUTE THEN
      STATE := 0;
      DONE := FALSE;
      ERROR := FALSE;
    END_IF;
ELSE
  STATE := 0;
END_CASE;

EXECUTE0 := EXECUTE;

(* CiA402 positive (0x60E0) and negative (0x60E1) torque limit values.
   CanFestival refuses a second transfer towards a node while one is still
   running, so they are read one after the other rather than in parallel. *)
CASE SDOSTEP OF
  0:
    IF EXECUTE AND NOT EXECUTE0 THEN
      SDOSTEP := 1;
      DONE := FALSE;
      ERROR := FALSE;
      ERRORID := 0;
      BUSY := TRUE;
    END_IF;
  1:
    SDO0(EXECUTE := TRUE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
         INDEX := 16#60E0, SUBINDEX := 0);
    IF SDO0.DONE THEN
      TORQUELIMITPOS := DWORD_TO_UINT(SDO0.VALUE);
      SDOSTEP := 2;
    ELSIF SDO0.ERROR THEN
      ERROR := TRUE;
      ERRORID := SDO0.ERRORID;
      SDOSTEP := 3;
    END_IF;
  2:
    SDO1(EXECUTE := TRUE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
         INDEX := 16#60E1, SUBINDEX := 0);
    IF SDO1.DONE THEN
      TORQUELIMITNEG := DWORD_TO_UINT(SDO1.VALUE);
      DONE := TRUE;
      SDOSTEP := 3;
    ELSIF SDO1.ERROR THEN
      ERROR := TRUE;
      ERRORID := SDO1.ERRORID;
      SDOSTEP := 3;
    END_IF;
  3:
    BUSY := FALSE;
    IF NOT EXECUTE THEN
      SDO0(EXECUTE := FALSE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
           INDEX := 16#60E0, SUBINDEX := 0);
      SDO1(EXECUTE := FALSE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
           INDEX := 16#60E1, SUBINDEX := 0);
      SDOSTEP := 0;
      DONE := FALSE;
      ERROR := FALSE;
    END_IF;
ELSE
  SDOSTEP := 0;
END_CASE;

EXECUTE0 := EXECUTE;

(* CiA402 positive (0x60E0) and negative (0x60E1) torque limit values,
   written one after the other. See CanOpenGetTorqueLimit. *)
CASE SDOSTEP OF
  0:
    IF EXECUTE AND NOT EXECUTE0 THEN
      SDOSTEP := 1;
      DONE := FALSE;
      ERROR := FALSE;
      ERRORID := 0;
      BUSY := TRUE;
    END_IF;
  1:
    SDO0(EXECUTE := TRUE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
         INDEX := 16#60E0, SUBINDEX := 0, SIZE := 2,
         VALUE := UINT_TO_DWORD(TORQUELIMITPOS));
    IF SDO0.DONE THEN
      SDOSTEP := 2;
    ELSIF SDO0.ERROR THEN
      ERROR := TRUE;
      ERRORID := SDO0.ERRORID;
      SDOSTEP := 3;
    END_IF;
  2:
    SDO1(EXECUTE := TRUE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
         INDEX := 16#60E1, SUBINDEX := 0, SIZE := 2,
         VALUE := UINT_TO_DWORD(TORQUELIMITNEG));
    IF SDO1.DONE THEN
      DONE := TRUE;
      SDOSTEP := 3;
    ELSIF SDO1.ERROR THEN
      ERROR := TRUE;
      ERRORID := SDO1.ERRORID;
      SDOSTEP := 3;
    END_IF;
  3:
    BUSY := FALSE;
    IF NOT EXECUTE THEN
      SDO0(EXECUTE := FALSE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
           INDEX := 16#60E0, SUBINDEX := 0, SIZE := 2,
           VALUE := UINT_TO_DWORD(TORQUELIMITPOS));
      SDO1(EXECUTE := FALSE, NETWORK := NETWORK, NODEID := INT_TO_USINT(POS),
           INDEX := 16#60E1, SUBINDEX := 0, SIZE := 2,
           VALUE := UINT_TO_DWORD(TORQUELIMITNEG));
      SDOSTEP := 0;
      DONE := FALSE;
      ERROR := FALSE;
    END_IF;
ELSE
  SDOSTEP := 0;
END_CASE;

EXECUTE0 := EXECUTE;
